import useGlobalStore from '@cetus/stores/src/global'
import { Flex } from '@chakra-ui/react'
import { lazy, useMemo } from 'react'
import { useLocation } from 'react-router-dom'
import PCMenus from '../menus/PCMenus'
import { IMenusProps } from '../type'
const UserActions = lazy(() => import('../userActions'))

const PCHeader = ({ menus, logo, setting, notifications, jump, isCetusPump, children }: IMenusProps) => {
  const { pathname } = useLocation()
  const { scrollYgtZero } = useGlobalStore()
  const firstPathPart = pathname.split('/').filter(Boolean)[0]
  const isShowBg = useMemo(() => {
    return (firstPathPart !== 'portfolio' && firstPathPart !== 'invite') || scrollYgtZero
  }, [scrollYgtZero, firstPathPart])
  return (
    <Flex
      w="100%"
      justifyContent="space-between"
      align="center"
      h="80px"
      p="0px 20px"
      position="sticky"
      zIndex="999"
      top="0px"
      background={!isShowBg ? 'transparent' : 'bg_primary'}
      transition="background-color 0.2s ease"
    >
      <PCMenus menus={menus} logo={logo} jump={jump} />
      <UserActions isCetusPump={isCetusPump} notifications={notifications} setting={setting}>
        {children}
      </UserActions>
    </Flex>
  )
}

export default PCHeader
