import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import useTokenSelectStore from '@cetus/stores/src/useTokenSelectStore'
import { Token } from '@cetus/types'
import { Heading, Modal, ModalBody, ModalCloseButton, ModalContent, ModalHeader, ModalOverlay } from '@chakra-ui/react'
import { memo, useCallback, useEffect, useRef, useState } from 'react'
import TokenSelectCard from './TokenSelectCard'
import { SelectType } from './type'

type TokenSelectModalProps<T extends SelectType = 'single'> = {
  isOpen: boolean
  haveImport?: boolean // 是否可以导入
  isDisableSelectTokenItem?: boolean // 是否禁止选择重复token
  isDcaSelect?: boolean // 是否是dca选择弹窗
  whiteTokenList?: Token[] // 白名单tokenlist
  isShowCollectListBox?: boolean // 是否显示热门token
  isShowOperate?: boolean // 是否显示最后三个操作按钮
  isShowTokenListTab?: boolean //是否显示default imported切换
  isShowLabelTab?: boolean // 是否显示label筛选
  isShowTokenName?: boolean
  tokenListMaxHeight?: string
  onClose: () => void
  selectType?: T
  // 必需的 props
  maxSelectNum: number
  onSelectToken: T extends 'single' ? (tokenInfo: Token) => void : (tokens: Token[]) => void
  value: T extends 'single' ? string | Token : string[] | Token[]
  [key: string]: any
  showSearchInput?: boolean
}
function TokenSelectModal<T extends SelectType>(props: TokenSelectModalProps<T>) {
  const { isApp } = useWindowWidth()
  const { isOpen, onClose } = props
  const { tokenModalOpacity } = useTokenSelectStore()
  const [maxHeight, setMaxHeight] = useState<string>('400px') // 设置默认值

  const calculateMaxHeightRef = useRef<() => void>()

  // 获取窗口高度
  const calculateMaxHeight = useCallback(() => {
    const windowHeight = window.innerHeight // 获取窗口的高度

    // 计算剩余高度并设置为最大高度
    let remainingHeight = windowHeight - (props?.selectType === 'single' ? (props.isShowCollectListBox ? 400 : 200) : 600)

    if (remainingHeight <= 128) {
      remainingHeight = 128
    }
    setMaxHeight(`${remainingHeight}px`)
  }, [props?.selectType])

  calculateMaxHeightRef.current = calculateMaxHeight

  // 监听窗口大小变化，动态更新maxHeight
  useEffect(() => {
    // 先清理之前的事件监听器
    if (calculateMaxHeightRef.current) {
      window.removeEventListener('resize', calculateMaxHeightRef.current)
    }

    calculateMaxHeight()

    window.addEventListener('resize', calculateMaxHeight)

    return () => {
      if (calculateMaxHeightRef.current) {
        window.removeEventListener('resize', calculateMaxHeightRef.current)
      }
    }
  }, [calculateMaxHeight])

  return (
    <Modal autoFocus={false} returnFocusOnClose={false} isOpen={isOpen} onClose={onClose} isCentered motionPreset="none">
      <ModalOverlay />
      <ModalContent minW={isApp ? '80%' : '462px'} opacity={tokenModalOpacity} transition="opacity 0.3s">
        <ModalHeader p="18px 16px">
          <Heading fontWeight="500" fontSize="16px">
            Select a token
          </Heading>
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody p="0" textAlign="center" overflow="hidden">
          <TokenSelectCard {...(props as any)} tokenListMaxHeight={maxHeight} />
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}

export default memo(TokenSelectModal)
