import { LocalForageService } from './local-forage-service'

// 单例模式实现
class VariousTokensTableImpl extends LocalForageService {
  private static instance: VariousTokensTableImpl

  private constructor() {
    super('CetusSite', 'variousTokens')
  }

  public static getInstance(): VariousTokensTableImpl {
    if (!VariousTokensTableImpl.instance) {
      VariousTokensTableImpl.instance = new VariousTokensTableImpl()
    }
    return VariousTokensTableImpl.instance
  }
}

// 为了保持向后兼容，保留静态方法接口
export class VariousTokensTable {
  private static table = VariousTokensTableImpl.getInstance()

  static async setItem<T>(key: string, value: T): Promise<void> {
    return VariousTokensTable.table.setItem(key, value)
  }

  static async getItem<T>(key: string): Promise<T | null> {
    return VariousTokensTable.table.getItem(key)
  }

  static async getAllItems<T>(): Promise<Map<string, T> | null> {
    return VariousTokensTable.table.getAllItems()
  }

  static async removeItem(key: string): Promise<void> {
    return VariousTokensTable.table.removeItem(key)
  }

  static async clear(): Promise<void> {
    return VariousTokensTable.table.clear()
  }
}
