import { Token } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import { textEllipses } from '@cetus/utils'
import { Button, ButtonProps, CenterProps, HStack, Skeleton, SkeletonCircle, Text, TextProps, useDisclosure } from '@chakra-ui/react'
import { lazy, memo, useState } from 'react'
import { useLocation } from 'react-router-dom'
import TokenAvatar from './TokenAvatar'
const TokenSelectModal = lazy(() => import('./tokenSelectModal'))

interface CoinSelectProps {
  value?: Token
  onSelect: (value: Token) => void
  loading?: boolean
  currentCoinKey?: string
  whiteTokenList?: Token[]
  tokenStyle?: CenterProps
  symbolTipStyle?: TextProps
  tokenSize?: string
  symbolStyle?: TextProps
  wrapStyle?: ButtonProps
  isShowLabelTab?: boolean
  isShowTokenListTab?: boolean
  isShowHotList?: boolean
  isShowCollectListBox?: boolean
  disabled?: boolean
  selectModalCallback?: (isOpen: boolean) => void
  openSelectTokenModal?: () => void
  isShowOperate?: boolean
  isShowTokenName?: boolean
  showSearchInput?: boolean
}

function CoinSelect({
  value,
  onSelect,
  loading,
  currentCoinKey,
  whiteTokenList,
  tokenStyle = {},
  tokenSize = '38px',
  symbolStyle = {},
  symbolTipStyle = {},
  wrapStyle = {},
  isShowLabelTab = true,
  isShowCollectListBox = true,
  isShowOperate = true,
  isShowTokenListTab = true,
  isShowHotList = true,
  disabled = false,
  openSelectTokenModal,
  selectModalCallback,
  isShowTokenName = true,
  showSearchInput = true
}: CoinSelectProps) {
  const { isOpen, onOpen, onClose } = useDisclosure()
  const [hover, setHover] = useState(false)
  const { pathname } = useLocation()

  return (
    <>
      <Button
        w="100%"
        variant="unstyled"
        display="flex"
        alignItems="center"
        gap="8px"
        onClick={() => {
          if (openSelectTokenModal) {
            openSelectTokenModal()
          } else {
            onOpen()
          }
          if (selectModalCallback) {
            selectModalCallback(true)
          }
        }}
        cursor="pointer"
        onMouseEnter={() => setHover(true)}
        onMouseLeave={() => setHover(false)}
        isDisabled={disabled}
        {...wrapStyle}
      >
        {loading ? (
          <HStack>
            <SkeletonCircle w={tokenSize} h={tokenSize} />
            <Skeleton h={symbolStyle.fontSize || '16px'} />
          </HStack>
        ) : value ? (
          <>
            <TokenAvatar
              variant="border"
              src={value?.logo_url || ''}
              coin_type={value?.coin_type}
              size={tokenSize}
              style={hover ? { ...tokenStyle, borderColor: 'token_active_border', boxShadow: '0px 0px 6px 0px #0067AD' } : tokenStyle}
            />

            <Text color="text_caption" fontSize="16px" fontWeight="600" {...symbolStyle}>
              {textEllipses(value?.symbol || '', 10)}
            </Text>
          </>
        ) : (
          <Text color="text_caption" fontSize="14px" fontWeight="600" {...symbolTipStyle}>
            Select a token
          </Text>
        )}

        <Icon xlinkHref="#icon-icon_arrow" fontSize="12px" svgFill={hover ? 'text_caption' : 'text_paragraph'} />
      </Button>
      {/* 如果在外部实现了TokenSelectModal，则不显示内部实现的TokenSelectModal */}
      {!openSelectTokenModal && (
        <TokenSelectModal
          showSearchInput={showSearchInput}
          tokenInfo={value}
          value={value?.coin_type || ''}
          isOpen={isOpen}
          currentCoinKey={currentCoinKey}
          whiteTokenList={whiteTokenList}
          isShowLabelTab={isShowLabelTab}
          isShowHotList={isShowHotList}
          isShowTokenListTab={isShowTokenListTab && !pathname?.includes('/dca')}
          isShowCollectListBox={isShowCollectListBox && !pathname?.includes('/dca')}
          isShowOperate={isShowOperate}
          isShowTokenName={isShowTokenName}
          onSelectToken={(tokenInfo: Token) => {
            onSelect(tokenInfo)
          }}
          onClose={() => {
            onClose()
            if (selectModalCallback) {
              selectModalCallback(false)
            }
          }}
        />
      )}
    </>
  )
}

export default memo(CoinSelect)
